import requests
from pathlib import Path
import zipfile
DOWNLOAD_DIR = Path("downloads")
ZIP_DIR = Path("unzipped_files")
def task_func(url, filename):
    """
    Downloads a ZIP file from the specified URL and extracts it.

    Args:
        url (str): The URL to download the ZIP file from.
        filename (str): The name to save the downloaded ZIP file as.

    Returns:
        tuple: (status_message, [list_of_extracted_filenames])
               On error, status_message contains "Error" and the list is [].
    """
    # Ensure directories exist
    try:
        DOWNLOAD_DIR.mkdir(parents=True, exist_ok=True)
        ZIP_DIR.mkdir(parents=True, exist_ok=True)
    except Exception as e:
        return (f"Error: Failed to create directories: {e}", [])

    zip_path = DOWNLOAD_DIR / filename

    # Download the file
    try:
        response = requests.get(url, stream=True, timeout=30)
        response.raise_for_status()
        with zip_path.open("wb") as f:
            for chunk in response.iter_content(chunk_size=8192):
                if chunk:
                    f.write(chunk)
    except requests.RequestException as e:
        return (f"Error: Failed to download file from {url}: {e}", [])
    except OSError as e:
        return (f"Error: Failed to write downloaded file: {e}", [])

    # Extract the ZIP file
    extracted_files = []
    try:
        with zipfile.ZipFile(zip_path, "r") as zip_ref:
            zip_ref.extractall(ZIP_DIR)
            for member in zip_ref.infolist():
                # Only list regular files, not directories
                if not member.is_dir():
                    extracted_files.append(str(ZIP_DIR / member.filename))
    except (zipfile.BadZipFile, zipfile.LargeZipFile) as e:
        return (f"Error: ZIP file is invalid or corrupted: {e}", [])
    except OSError as e:
        return (f"Error: Failed during file extraction: {e}", [])

    return ("Download and extraction successful", extracted_files)

import re
from urllib.parse import urlparse
from bs4 import BeautifulSoup
import requests
def task_func(myString):
    # Regex to find URLs (basic, but works for typical cases)
    url_pattern = re.compile(
        r'(https?://[^\s]+)',
        re.IGNORECASE
    )
    match = url_pattern.search(myString)
    if not match:
        return "No valid URL found in the provided string."

    url = match.group(1)

    # Validate URL structure
    parsed = urlparse(url)
    if not parsed.scheme or not parsed.netloc:
        return "No valid URL found in the provided string."

    try:
        response = requests.get(url, timeout=10)
    except Exception:
        return f"Unable to fetch the content of the URL: {url}"

    if not (200 <= response.status_code < 300):
        return f"Unable to fetch the content of the URL: {url}"

    # Parse HTML to get title
    soup = BeautifulSoup(response.text, "html.parser")
    title_tag = soup.find("title")
    if not title_tag or not title_tag.get_text(strip=True):
        return "No title tag found in the webpage."

    return title_tag.get_text(strip=True)

import re
import json
import requests
def task_func(data_url: str) -> list:
    try:
        response = requests.get(data_url)
        text = response.text
    except Exception:
        return ["Invalid url input"]

    # Try parsing JSON; if it fails, we'll treat the whole text as non-JSON
    try:
        data = response.json()
        json_text = json.dumps(data)
    except Exception:
        json_text = text

    # Remove any content inside square brackets to ignore names there
    cleaned = re.sub(r"\[[^\]]*\]", "", json_text)

    # Heuristic regex for names: words starting with capital letters,
    # possibly containing hyphens or apostrophes, and possibly multi-word names.
    # Example matches: "John", "Mary Jane", "O'Connor", "Jean-Luc Picard"
    name_pattern = re.compile(
        r'\b([A-Z][a-zA-Z\'-]*(?:\s+[A-Z][a-zA-Z\'-]*)*)\b'
    )

    candidates = name_pattern.findall(cleaned)

    # Remove obvious JSON keys / common non-name tokens
    # (since we're not given a strict schema, keep filtering minimal)
    blacklist = {
        "True", "False", "None", "Null", "JSON", "URL", "Http", "Https"
    }

    names = []
    for c in candidates:
        c_strip = c.strip()
        if not c_strip:
            continue
        if c_strip in blacklist:
            continue
        # Avoid duplicates while preserving order
        if c_strip not in names:
            names.append(c_strip)

    return names
